        return new long[0][];
    }

    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        in.nextToken();
        int n = (int) in.nval;
        long[][] a = new long[n][2];
        for (int i = 0; i < n; i++) {
            in.nextToken(); a[i][0] = (long) in.nval;
            in.nextToken(); a[i][1] = (long) in.nval;
        }
        in.nextToken();
        int m = (int) in.nval;
        long[][] b = new long[m][2];
        for (int i = 0; i < m; i++) {
            in.nextToken(); b[i][0] = (long) in.nval;
            in.nextToken(); b[i][1] = (long) in.nval;
        }
        long[][] res = addPolynomials(a, b);
        StringBuilder sb = new StringBuilder();
        sb.append(res.length).append("\n");
        for (long[] t : res) sb.append(t[0]).append(" ").append(t[1]).append("\n");
        System.out.print(sb);
    }
